steps.preRequestScript:
// PRE-REQUEST do AirSearch na receita "partida em menos de N horas".
// Dois passos usam este script: o de HOJE (DAY_OFFSET = 0) e o de AMANHÃ (DAY_OFFSET = 1),
// porque a janela de 24h atravessa a meia-noite e o runtime não tem pm.setNextRequest.
// O body da busca usa {{flowSearchDate}} como data de partida (resolvido depois deste script).
var DAY_OFFSET = 0;
var moment = require("moment");
pm.environment.set("flowSearchDate", moment().add(DAY_OFFSET, "days").format("YYYY-MM-DD"));
// Só no passo de HOJE: começa vazio — nunca reaproveite o voo de outra execução.
if (DAY_OFFSET === 0) {
  pm.environment.set("journeyKeyIda", "");
  pm.environment.set("fareKeyIda", "");
  pm.environment.set("flowDepartureAt", "");
}

steps.postResponseScript:
// POST-RESPONSE do AirSearch na receita "partida em menos de N horas" (o mesmo nos dois
// passos, hoje e amanhã). Escolhe o 1º voo com tarifa cuja partida está entre
// agora + MIN_HOURS e agora + MAX_HOURS. O passo de amanhã só grava se o de hoje não achou.
(function () {
  // === Caminhos da resposta (confirmados no run de 13/11/2026 — catálogo B2B, AirSearch v3) ===
  // data.airResult.offers[] → offersAvailableByMarket[] → value[] = os voos.
  var OFFERS_PATH = "data.airResult.offers";
  var MARKETS_FIELD = "offersAvailableByMarket";
  var JOURNEYS_FIELD = "value";
  var DEPARTURE_PATH = "designator.departure";  // ex. "2026-11-14T06:00:00": hora local, sem fuso
  var JOURNEY_KEY_FIELD = "key";
  var FARES_FIELD = "fares";
  var FARE_KEY_FIELD = "key";
  // === Janela (da resposta do usuário; padrão 2h a 24h) ===
  var MIN_HOURS = <<minHours.number>>;
  var MAX_HOURS = 24;

  var moment = require("moment");
  if (pm.environment.get("journeyKeyIda")) return;  // o passo de hoje já achou

  function get(obj, path) {
    return path.split(".").reduce(function (acc, key) { return acc == null ? undefined : acc[key]; }, obj);
  }
  var offers = get(pm.response.json(), OFFERS_PATH) || [];
  var now = moment();
  for (var o = 0; o < offers.length; o++) {
    var markets = offers[o][MARKETS_FIELD] || [];
    for (var m = 0; m < markets.length; m++) {
      var journeys = markets[m][JOURNEYS_FIELD] || [];
      for (var i = 0; i < journeys.length; i++) {
        var journey = journeys[i];
        var fare = (journey[FARES_FIELD] || [])[0];
        var raw = get(journey, DEPARTURE_PATH);
        if (!fare || !raw) continue;
        var departure = moment(raw);
        var hours = departure.diff(now, "hours", true);
        if (hours >= MIN_HOURS && hours < MAX_HOURS) {
          pm.environment.set("journeyKeyIda", journey[JOURNEY_KEY_FIELD]);
          pm.environment.set("fareKeyIda", fare[FARE_KEY_FIELD]);
          pm.environment.set("flowDepartureAt", departure.format());
          return;
        }
      }
    }
  }
  console.log("Nenhum voo com partida entre " + MIN_HOURS + "h e " + MAX_HOURS + "h nesta busca.");
})();

